server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/selfsigned.crt;
    ssl_certificate_key /etc/nginx/ssl/selfsigned.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    root /var/www/main;
    index index.html;

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
        try_files $uri $uri/index.html =404;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}

